Action.Str:
// POST audio to deepthought n8n, get text response
var audioPath = "/sdcard/hl_voice.m4a";
var url = "http://192.168.42.150:5678/webhook/voice-text";
var boundary = "Boundary" + Date.now();
var resp = "Error: could not reach deepthought";
try {
  var f = new java.io.File(audioPath);
  var fis = new java.io.FileInputStream(f);
  var bytes = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, f.length());
  fis.read(bytes);
  fis.close();

  var conn = new java.net.URL(url).openConnection();
  conn.setRequestMethod("POST");
  conn.setDoOutput(true);
  conn.setConnectTimeout(10000);
  conn.setReadTimeout(90000);
  conn.setRequestProperty("Content-Type", "multipart/form-data; boundary=" + boundary);

  var out = new java.io.DataOutputStream(conn.getOutputStream());
  out.writeBytes("--" + boundary + "\r\n");
  out.writeBytes("Content-Disposition: form-data; name=\"audio\"; filename=\"voice.m4a\"\r\n");
  out.writeBytes("Content-Type: audio/mp4\r\n\r\n");
  out.write(bytes);
  out.writeBytes("\r\n--" + boundary + "--\r\n");
  out.flush();
  out.close();

  var br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream()));
  var line; var body = "";
  while ((line = br.readLine()) != null) { body += line; }
  br.close();

  var parsed = JSON.parse(body);
  resp = parsed.response || "No response from server";
} catch(e) {
  resp = "Error: " + e.message;
}
setLocal("HL_RESPONSE", resp);
